diff --git a/rust/fsl-runtime/tests/reviewgraphen_generated_calibration_20.rs b/rust/fsl-runtime/tests/reviewgraphen_generated_calibration_20.rs
new file mode 100644
--- /dev/null
+++ b/rust/fsl-runtime/tests/reviewgraphen_generated_calibration_20.rs
@@ -0,0 +1,38 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use std::collections::BTreeMap;
+
+use fsl_core::{FsResolver, KernelExpr, build_model, parse_kernel_source};
+use fsl_runtime::verification_warnings;
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let kernel = parse_kernel_source(
+        r"
+spec WarningGap {
+  state { ok: Bool }
+  init { ok = true }
+  invariant Guarded { ok => ok }
+}
+",
+        &FsResolver::new(std::env::temp_dir()),
+    )
+    .expect("parse model");
+    let mut model = build_model(kernel).expect("build model");
+    let KernelExpr::Binary { left, .. } = &mut model.invariants[0].expr else {
+        panic!("expected implication");
+    };
+    *left = Box::new(KernelExpr::Var("missing".to_owned()));
+
+    let warnings = verification_warnings(
+        &model,
+        0,
+        false,
+        None,
+        None,
+        &BTreeMap::new(),
+    );
+    let warning = warnings
+        .iter()
+        .find(|warning| warning["kind"].as_str() == Some("vacuity_check_failed"))
+        .expect("reachability evaluation failure must be surfaced");
+    assert_eq!(warning["name"].as_str(), Some("Guarded"));
+    assert!(warning["message"].as_str().is_some_and(|message| message.contains("unknown identifier 'missing'")));
+}
